public void SetZeroes(int[][] matrix)
{
    int m = matrix.Length, n = matrix[0].Length;
    bool[] rows = new bool[m];
    bool[] cols = new bool[n];

    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++)
            if (matrix[r][c] == 0) { rows[r] = true; cols[c] = true; }

    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++)
            if (rows[r] || cols[c]) matrix[r][c] = 0;
}

public void SetZeroes(int[][] matrix)
{
    int m = matrix.Length, n = matrix[0].Length;
    bool firstRowHasZero = false, firstColHasZero = false;

    for (int c = 0; c < n; c++) if (matrix[0][c] == 0) firstRowHasZero = true;
    for (int r = 0; r < m; r++) if (matrix[r][0] == 0) firstColHasZero = true;

    for (int r = 1; r < m; r++)
        for (int c = 1; c < n; c++)
            if (matrix[r][c] == 0)
            {
                matrix[r][0] = 0;
                matrix[0][c] = 0;
            }

    for (int r = 1; r < m; r++)
        for (int c = 1; c < n; c++)
            if (matrix[r][0] == 0 || matrix[0][c] == 0)
                matrix[r][c] = 0;

    if (firstRowHasZero) for (int c = 0; c < n; c++) matrix[0][c] = 0;
    if (firstColHasZero) for (int r = 0; r < m; r++) matrix[r][0] = 0;
}
